// Sticky navigation
$(window).on("scroll", function() {
  if ($(window).scrollTop()) {
    $("#header").addClass("is-sticky");
  } else {
    $("#header").removeClass("is-sticky");
  }
});

// Scrollspy for navigation
// Cache selectors
var lastId,
  topMenu = $(".nav-list"),
  topMenuHeight = topMenu.outerHeight(),
  // All list items
  menuItems = topMenu.find("a"),
  // Anchors corresponding to menu items
  scrollItems = menuItems.map(function() {
    var item = $($(this).attr("href"));
    if (item.length) {
      return item;
    }
  });

// Bind click handler to menu items
// so we can get a fancy scroll animation
menuItems.click(function(e) {
  var href = $(this).attr("href"),
    offsetTop = href === "#" ? 0 : $(href).offset().top - topMenuHeight + 1;
  $("html, body")
    .stop()
    .animate(
      {
        scrollTop: offsetTop
      },
      800
    );
  e.preventDefault();
});

// Bind to scroll
$(window).scroll(function() {
  // Get container scroll position
  var fromTop = $(this).scrollTop() + topMenuHeight;

  // Get id of current scroll item
  var cur = scrollItems.map(function() {
    if ($(this).offset().top < fromTop) return this;
  });
  // Get the id of the current element
  cur = cur[cur.length - 1];
  var id = cur && cur.length ? cur[0].id : "";

  if (lastId !== id) {
    lastId = id;
    // Set/remove active class
    menuItems
      .parent()
      .removeClass("active")
      .end()
      .filter("[href='#" + id + "']")
      .parent()
      .addClass("active");
  }
});

// Navigation layout for xs to md screens

$(".mob-nav").click(function(event) {
  event.stopPropagation();
  $(".mob-nav-container").addClass("show");
});

$(".close-btn i").click(function(event) {
  event.stopPropagation();
  $(".mob-nav-container").removeClass("show");
});

$(".mob-nav-container li").click(function(event) {
  event.stopPropagation();
  $(".mob-nav-container").removeClass("show");
});

$(document).on("click", function(event) {
  if (!$(event.target).closest(".mob-nav-container").length) {
    $(".mob-nav-container").removeClass("show");
  }
});

